 * Parsing and validation of the build-graph text format read on standard
 * input. Produces a map of task costs and a map of dependency edges, or
 * throws a `CliError` describing the first problem found.
 */

const NAME_PATTERN = /^[A-Za-z0-9_.-]+$/
const COST_PATTERN = /^[0-9]+$/

export class CliError extends Error {
  constructor(message, code) {
    super(message)
    this.code = code
  }
}

/**
 * Parses the raw input text into a graph: a `tasks` map from name to cost,
 * and an `edges` map from name to the set of names it depends on.
 */
export function parseGraph(input) {
  const lines = input.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()

  const tasks = new Map()
  const depLines = []

  for (let i = 0; i < lines.length; i++) {
    const lineNo = i + 1
    const trimmed = lines[i].trim()
    if (trimmed === '' || trimmed.startsWith('#')) continue

    const words = trimmed.split(/\s+/)
    const directive = words[0]

    if (directive === 'task') {
      if (words.length !== 3) {
        throw new CliError(`error: line ${lineNo}: expected task <name> <cost>`, 2)
      }
      const [, name, costText] = words
      if (!NAME_PATTERN.test(name)) {
        throw new CliError(`error: line ${lineNo}: invalid task name ${name}`, 2)
      }
      if (!COST_PATTERN.test(costText)) {
        throw new CliError(`error: line ${lineNo}: cost must be a non-negative integer`, 2)
      }
      if (tasks.has(name)) {
        throw new CliError(`error: line ${lineNo}: task ${name} is declared twice`, 2)
      }
      tasks.set(name, { cost: parseInt(costText, 10) })
    } else if (directive === 'dep') {
      if (words.length < 3) {
        throw new CliError(`error: line ${lineNo}: expected dep <name> <dependency>...`, 2)
      }
      depLines.push({ name: words[1], dependencies: words.slice(2) })
    } else {
      throw new CliError(`error: line ${lineNo}: unknown directive ${directive}`, 2)
    }
  }

  for (const { name, dependencies } of depLines) {
    if (!tasks.has(name)) throw new CliError(`error: unknown task ${name}`, 2)
    for (const dependency of dependencies) {
      if (!tasks.has(dependency)) throw new CliError(`error: unknown task ${dependency}`, 2)
    }
  }

  const edges = new Map()
  for (const name of tasks.keys()) edges.set(name, new Set())
  for (const { name, dependencies } of depLines) {
    const set = edges.get(name)
    for (const dependency of dependencies) set.add(dependency)
  }

  return { tasks, edges }
}
"}

