{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/e3-attempts-t5-20260921T220951Z/cell-bFvJUz/src/graph.js","content":"/**
 * Graph analysis shared by the `waves`, `explain` and `pack` commands:
 * cycle detection, the unlimited-worker schedule (start/finish/depth), and
 * the downstream-chain priority used to break ties while packing.
 */

/**
 * Finds the first cycle a depth-first search encounters, walking tasks and
 * each task's dependencies in ascending name order. Returns the cycle as an
 * array of names starting and ending with the re-entered task, or `null`
 * when the graph is acyclic.
 */
export function findCycle(tasks, edges) {
  const names = [...tasks.keys()].sort()
  const visited = new Set()
  const onStack = new Set()
  const stack = []

  function visit(name) {
    if (onStack.has(name)) {
      const index = stack.indexOf(name)
      return stack.slice(index).concat([name])
    }
    if (visited.has(name)) return null

    stack.push(name)
    onStack.add(name)
    for (const dependency of [...edges.get(name)].sort()) {
      const found = visit(dependency)
      if (found) return found
    }
    stack.pop()
    onStack.delete(name)
    visited.add(name)
    return null
  }

  for (const name of names) {
    if (!visited.has(name)) {
      const found = visit(name)
      if (found) return found
    }
  }
  return null
}

/**
 * Computes, for every task, the start and finish time in the unlimited-
 * worker schedule and the wave (depth) it belongs to. Assumes the graph is
 * acyclic.
 */
export function computeSchedule(tasks, edges) {
  const start = new Map()
  const finish = new Map()
  const depth = new Map()

  function resolve(name) {
    if (finish.has(name)) return
    const dependencies = edges.get(name)
    let taskStart = 0
    let taskDepth = 0
    if (dependencies.size > 0) {
      let maxFinish = 0
      let maxDepth = -1
      for (const dependency of dependencies) {
        resolve(dependency)
        if (finish.get(dependency) > maxFinish) maxFinish = finish.get(dependency)
        if (depth.get(dependency) > maxDepth) maxDepth = depth.get(dependency)
      }
      taskStart = maxFinish
      taskDepth = maxDepth + 1
    }
    start.set(name, taskStart)
    finish.set(name, taskStart + tasks.get(name).cost)
    depth.set(name, taskDepth)
  }

  for (const name of tasks.keys()) resolve(name)
  return { start, finish, depth }
}

/**
 * Computes, for every task, the cost of the longest chain that begins at it
 * and runs through its dependents down to a task nothing depends on.
 */
export function computePriority(tasks, edges) {
  const dependents = new Map()
  for (const name of tasks.keys()) dependents.set(name, [])
  for (const [name, dependencies] of edges) {
    for (const dependency of dependencies) dependents.get(dependency).push(name)
  }

  const priority = new Map()
  function resolve(name) {
    if (priority.has(name)) return priority.get(name)
    let best = 0
    for (const dependent of dependents.get(name)) {
      const value = resolve(dependent)
      if (value > best) best = value
    }
    const value = tasks.get(name).cost + best
    priority.set(name, value)
    return value
  }

  for (const name of tasks.keys()) resolve(name)
  return priority
}
"}

