{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/e3-attempts-t5-20260921T220951Z/cell-bFvJUz/src/pack.js","content":"/**
 * The `pack` simulation: assigns ready tasks to free workers, preferring the
 * task with the greatest downstream-chain priority and breaking ties by
 * ascending name, until every task has run.
 */

import { computePriority } from './graph.js'

/**
 * Runs the worker simulation and returns each worker's ordered task runs and
 * the finish time of every task.
 */
export function pack(tasks, edges, workerCount) {
  const priority = computePriority(tasks, edges)
  const remaining = new Set(tasks.keys())
  const finishTimes = new Map()
  const workerFreeAt = new Array(workerCount).fill(0)
  const workerRuns = Array.from({ length: workerCount }, () => [])

  let time = 0
  while (remaining.size > 0) {
    for (;;) {
      const ready = []
      for (const name of remaining) {
        let allDone = true
        for (const dependency of edges.get(name)) {
          if (!(finishTimes.has(dependency) && finishTimes.get(dependency) <= time)) {
            allDone = false
            break
          }
        }
        if (allDone) ready.push(name)
      }
      if (ready.length === 0) break

      let workerIndex = -1
      for (let i = 0; i < workerCount; i++) {
        if (workerFreeAt[i] <= time) {
          workerIndex = i
          break
        }
      }
      if (workerIndex === -1) break

      ready.sort((a, b) => priority.get(b) - priority.get(a) || (a < b ? -1 : 1))
      const name = ready[0]
      const cost = tasks.get(name).cost
      const finish = time + cost
      workerRuns[workerIndex].push({ name, start: time, finish })
      workerFreeAt[workerIndex] = finish
      finishTimes.set(name, finish)
      remaining.delete(name)
    }

    if (remaining.size === 0) break

    let next = Infinity
    for (const freeAt of workerFreeAt) {
      if (freeAt > time && freeAt < next) next = freeAt
    }
    time = next
  }

  return { workerRuns, finishTimes }
}
"}

