{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/e3-attempts-t5-20260921T220951Z/cell-bFvJUz/src/cli.js","content":"#!/usr/bin/env node
/**
 * The command. `node src/cli.js waves`, `node src/cli.js explain` and
 * `node src/cli.js pack <workers>` each report on the build graph read from
 * standard input.
 */

import { readFileSync } from 'node:fs'
import { CliError, parseGraph } from './parse.js'
import { computeSchedule, findCycle } from './graph.js'
import { pack } from './pack.js'

const USAGE = 'error: usage: cli.js waves|explain|pack <workers>'
const WORKERS_PATTERN = /^[1-9][0-9]*$/

function fail(message, code) {
  process.stderr.write(`${message}\n`)
  process.exit(code)
}

function parseArgs(argv) {
  if (argv.length === 1 && (argv[0] === 'waves' || argv[0] === 'explain')) {
    return { mode: argv[0] }
  }
  if (argv.length === 2 && argv[0] === 'pack') {
    if (!WORKERS_PATTERN.test(argv[1])) {
      fail('error: workers must be a positive integer', 2)
    }
    return { mode: 'pack', workers: parseInt(argv[1], 10) }
  }
  fail(USAGE, 2)
  return undefined
}

function runWaves(tasks, edges) {
  const { finish, depth } = computeSchedule(tasks, edges)
  const waveCount = tasks.size === 0 ? 0 : Math.max(...depth.values()) + 1
  const waves = Array.from({ length: waveCount }, () => [])
  for (const name of tasks.keys()) waves[depth.get(name)].push(name)

  const lines = []
  for (let i = 0; i < waveCount; i++) {
    lines.push(`wave ${i}: ${waves[i].sort().join(' ')}`)
  }
  const total = tasks.size === 0 ? 0 : Math.max(...finish.values())
  lines.push(`total ${total}`)
  process.stdout.write(lines.join('\n') + '\n')
}

function runExplain(tasks, edges) {
  const { start, finish, depth } = computeSchedule(tasks, edges)
  const names = [...tasks.keys()].sort()
  const lines = names.map(
    (name) => `${name} start=${start.get(name)} finish=${finish.get(name)} depth=${depth.get(name)}`,
  )
  const total = tasks.size === 0 ? 0 : Math.max(...finish.values())
  lines.push(`total ${total}`)
  process.stdout.write(lines.join('\n') + '\n')
}

function runPack(tasks, edges, workerCount) {
  const { workerRuns, finishTimes } = pack(tasks, edges, workerCount)
  const lines = workerRuns.map((runs, i) => {
    const entries = runs.map((run) => ` ${run.name}@${run.start}-${run.finish}`).join('')
    return `worker ${i}:${entries}`
  })
  const makespan = finishTimes.size === 0 ? 0 : Math.max(...finishTimes.values())
  lines.push(`makespan ${makespan}`)
  process.stdout.write(lines.join('\n') + '\n')
}

function main() {
  const { mode, workers } = parseArgs(process.argv.slice(2))

  let input
  try {
    input = readFileSync(0, 'utf8')
  } catch {
    input = ''
  }

  let tasks
  let edges
  try {
    ;({ tasks, edges } = parseGraph(input))
  } catch (error) {
    if (error instanceof CliError) fail(error.message, error.code)
    throw error
  }

  const cycle = findCycle(tasks, edges)
  if (cycle) fail(`error: cycle: ${cycle.join(' -> ')}`, 3)

  if (mode === 'waves') runWaves(tasks, edges)
  else if (mode === 'explain') runExplain(tasks, edges)
  else runPack(tasks, edges, workers)
}

main()
"}

